            dist = distance(pedestrian, pathway)
            if dist < min_distance:
                min_distance = dist
                closest_pathway = pathway
        pedestrian_pathway_pairs.append((pedestrian, closest_pathway))

    pedestrian_plaza_pairs = []
    for pedestrian in pedestrian_patches:
        min_distance = float('inf')
        closest_plaza = None
        for plaza in plaza_patches:
            dist = distance(pedestrian, plaza)
            if dist < min_distance:
                min_distance = dist
                closest_plaza = plaza
        pedestrian_plaza_pairs.append((pedestrian, closest_plaza))

